		assertTrue(LocalDefenceSpecDetector.recordsSplashAsMiss(SpecialWeapon.ACCURSED_SCEPTRE));
		assertFalse(LocalDefenceSpecDetector.recordsSplashAsMiss(SpecialWeapon.SEERCULL));
