package net.betterpartydefence;

import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import net.betterpartydefence.DefenceTracker.DefenceState;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Draws the tracked NPC's Defence in scene space. */
public class NpcDefenceOverlay extends Overlay
{
	private final Client client;
	private final DefenceTracker tracker;
	private final BetterPartyDefenceConfig config;
	private final TrackerFontManager fontManager;
	private final DefenceOverlayRenderer renderer;
	private final PreviousTargetDisplayState previousTargetState;
	private final InitialSyncDisplayGate initialSyncDisplayGate;

	public NpcDefenceOverlay(Client client, DefenceTracker tracker, BetterPartyDefenceConfig config,
		SkillIconSource skillIcons, TrackerFontManager fontManager,
		PreviousTargetDisplayState previousTargetState, InitialSyncDisplayGate initialSyncDisplayGate)
	{
		this.client = client;
		this.tracker = tracker;
		this.config = config;
		this.fontManager = fontManager;
		this.renderer = new DefenceOverlayRenderer(config, skillIcons);
		this.previousTargetState = previousTargetState;
		this.initialSyncDisplayGate = initialSyncDisplayGate;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.defenceHpBar())
		{
			return null;
		}

		graphics.setFont(fontManager.font());
		DefenceState current = tracker.state();
		List<DefenceState> states = tracker.states();

		if (!config.previousTargetDisplay())
		{
			renderLegacyAttached(graphics, states);
			return null;
		}

		renderMainTarget(graphics, current);

		DefenceState previous = previousTargetState.previousState();
		if (previous != null)
		{
			NPC npc = liveNpc(previous.getNpcIndex());
			if (npc != null)
			{
				renderAtNpc(graphics, previous, npc,
					config.defenceHpBarPosition(), config.defenceHpBarYOffset());
			}
		}
		return null;
	}

	/** Exact pre-feature attached rendering path, used whenever the experiment is disabled. */
	private void renderLegacyAttached(Graphics2D graphics, List<DefenceState> states)
	{
		DefenceOverlayPosition position = config.defenceHpBarPosition();
		for (DefenceState state : states)
		{
			if (!isDisplayable(state))
			{
				continue;
			}
			NPC npc = liveNpc(state.getNpcIndex());
			if (npc != null)
			{
				renderAtNpc(graphics, state, npc, position, config.defenceHpBarYOffset());
			}
		}
	}

	private void renderMainTarget(Graphics2D graphics, DefenceState current)
	{
		if (!isDisplayable(current))
		{
			return;
		}
		NPC npc = liveNpc(current.getNpcIndex());
		if (npc != null)
		{
			renderAtNpc(graphics, current, npc,
				config.defenceHpBarPosition(), config.defenceHpBarYOffset());
		}
	}

	private void renderAtNpc(Graphics2D graphics, DefenceState state, NPC npc,
		DefenceOverlayPosition position, int yOffset)
	{
		int zOffset = (int) (npc.getLogicalHeight() * position.getHeightFactor()) + position.getHeightOffset();
		Point anchor = npc.getCanvasTextLocation(graphics, "", zOffset);
		if (anchor == null)
		{
			return;
		}
		int centreX = anchor.getX() + position.getXNudge();
		int baseline = anchor.getY() - yOffset;
		renderer.renderAt(graphics, state, centreX, baseline);
	}

	private boolean isDisplayable(DefenceState state)
	{
		// The checkbox controls only optional pre-spec preview. Any actual local/party drain
		// remains displayable because drained=true is part of the stored/shared state.
		return state != null
			&& (state.isDrained() || config.defenceAlwaysShow())
			&& state.getNpcIndex() >= 0
			&& !initialSyncDisplayGate.isWaiting(state, client.getTickCount());
	}

	private NPC liveNpc(int index)
	{
		if (index < 0 || client.getTopLevelWorldView() == null || client.getTopLevelWorldView().npcs() == null)
		{
			return null;
		}
		NPC npc = client.getTopLevelWorldView().npcs().byIndex(index);
		return npc != null && !npc.isDead() && npc.getHealthRatio() != 0 ? npc : null;
	}
}

package net.betterpartydefence;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.betterpartydefence.DefenceTracker.SpecHistoryEntry;
import net.betterpartydefence.DefenceTracker.SyncState;
import net.runelite.client.party.messages.PartyMemberMessage;
import net.runelite.client.plugins.specialcounter.SpecialWeapon;

/**
 * Experimental Better Party Defence party message. This is deliberately additive to RuneLite's
 * normal SpecialCounterUpdate path: it carries an absolute tracker snapshot so another BPD user
 * in the same encounter can stay in sync even when that boss actor is not loaded on their client.
 */
public class BpdDefenceSync extends PartyMemberMessage
{
	public static final int PROTOCOL_VERSION = 1;
	public static final int SCOPE_WORLD = 0;
	public static final int SCOPE_COX = 1;
	public static final int SCOPE_TOB = 2;
	public static final int SCOPE_INSTANCE = 3;

	private int protocolVersion;
	private int world;
	private String bossType;
	private String bossName;
	private int scopeType;
	private int scopeId;
	private int bossX;
	private int bossY;
	private int bossPlane;
	private int healthPercent;
	private long sentAtMillis;
	/** Monotonic per-encounter logical state version used to reject stale peer snapshots. */
	private long stateVersion;

	private long current;
	private long min;
	private long base;
	private long attackLevel;
	private long strengthLevel;
	private long magicLevel;
	private long magicBaseLevel;
	private long magicDef;
	private long magicBaseDef;
	private boolean magicUsesDefence;
	private boolean demon;
	private boolean accursedApplied;
	private boolean drained;

	private List<String> historyPlayers;
	private List<String> historyWeapons;
	private List<Integer> historyHits;

	/** Required for party-message deserialisation. */
	public BpdDefenceSync()
	{
	}

	public BpdDefenceSync(
		int world,
		SyncState state,
		int scopeType,
		int scopeId,
		int bossX,
		int bossY,
		int bossPlane,
		int healthPercent)
	{
		this(world, state, scopeType, scopeId, bossX, bossY, bossPlane, healthPercent, 0L);
	}

	public BpdDefenceSync(
		int world,
		SyncState state,
		int scopeType,
		int scopeId,
		int bossX,
		int bossY,
		int bossPlane,
		int healthPercent,
		long stateVersion)
	{
		this.protocolVersion = PROTOCOL_VERSION;
		this.world = world;
		this.bossType = state.getBossType().name();
		this.bossName = state.getBossName();
		this.scopeType = scopeType;
		this.scopeId = scopeId;
		this.bossX = bossX;
		this.bossY = bossY;
		this.bossPlane = bossPlane;
		this.healthPercent = healthPercent;
		this.sentAtMillis = System.currentTimeMillis();
		this.stateVersion = Math.max(0L, stateVersion);
		this.current = state.getCurrent();
		this.min = state.getMin();
		this.base = state.getBase();
		this.attackLevel = state.getAttackLevel();
		this.strengthLevel = state.getStrengthLevel();
		this.magicLevel = state.getMagicLevel();
		this.magicBaseLevel = state.getMagicBaseLevel();
		this.magicDef = state.getMagicDef();
		this.magicBaseDef = state.getMagicBaseDef();
		this.magicUsesDefence = state.isMagicUsesDefence();
		this.demon = state.isDemon();
		this.accursedApplied = state.isAccursedApplied();
		this.drained = state.isDrained();

		List<SpecHistoryEntry> history = state.getHistory();
		this.historyPlayers = new ArrayList<>(history.size());
		this.historyWeapons = new ArrayList<>(history.size());
		this.historyHits = new ArrayList<>(history.size());
		for (SpecHistoryEntry entry : history)
		{
			historyPlayers.add(entry.getPlayerName());
			historyWeapons.add(entry.getWeapon() == null ? "" : entry.getWeapon().name());
			historyHits.add(entry.getHit());
		}
	}

	public SyncState toSyncState()
	{
		BossDefence boss;
		try
		{
			boss = BossDefence.valueOf(bossType);
		}
		catch (RuntimeException ex)
		{
			return null;
		}

		List<SpecHistoryEntry> history = new ArrayList<>();
		int size = Math.min(
			historyPlayers == null ? 0 : historyPlayers.size(),
			Math.min(historyWeapons == null ? 0 : historyWeapons.size(), historyHits == null ? 0 : historyHits.size()));
		for (int i = 0; i < size; i++)
		{
			try
			{
				String weaponName = historyWeapons.get(i);
				Integer hit = historyHits.get(i);
				if (weaponName == null || hit == null)
				{
					continue;
				}
				SpecialWeapon weapon = SpecialWeapon.valueOf(weaponName);
				String player = historyPlayers.get(i);
				if (player == null || player.trim().isEmpty())
				{
					player = "Unknown";
				}
				history.add(new SpecHistoryEntry(player, weapon, hit));
			}
			catch (RuntimeException ignored)
			{
				// Ignore a history row from a newer/unknown protocol rather than dropping the snapshot.
			}
		}

		return new SyncState(
			bossName == null ? boss.getNpcName() : bossName,
			boss,
			current,
			min,
			base,
			attackLevel,
			strengthLevel,
			magicLevel,
			magicBaseLevel,
			magicDef,
			magicBaseDef,
			magicUsesDefence,
			demon,
			accursedApplied,
			drained,
			Collections.unmodifiableList(history));
	}

	public int getProtocolVersion() { return protocolVersion; }
	public int getWorld() { return world; }
	public String getBossType() { return bossType; }
	public String getBossName() { return bossName; }
	public int getScopeType() { return scopeType; }
	public int getScopeId() { return scopeId; }
	public int getBossX() { return bossX; }
	public int getBossY() { return bossY; }
	public int getBossPlane() { return bossPlane; }
	public int getHealthPercent() { return healthPercent; }
	public long getSentAtMillis() { return sentAtMillis; }
	public long getStateVersion() { return stateVersion; }
	public long getCurrent() { return current; }
	public long getMin() { return min; }
	public long getBase() { return base; }
	public long getAttackLevel() { return attackLevel; }
	public long getStrengthLevel() { return strengthLevel; }
	public long getMagicLevel() { return magicLevel; }
	public long getMagicBaseLevel() { return magicBaseLevel; }
	public long getMagicDef() { return magicDef; }
	public long getMagicBaseDef() { return magicBaseDef; }
	public boolean isMagicUsesDefence() { return magicUsesDefence; }
	public boolean isDemon() { return demon; }
	public boolean isAccursedApplied() { return accursedApplied; }
	public boolean isDrained() { return drained; }
	public List<String> getHistoryPlayers() { return historyPlayers; }
	public List<String> getHistoryWeapons() { return historyWeapons; }
	public List<Integer> getHistoryHits() { return historyHits; }
}

package net.betterpartydefence;

import java.awt.Color;
import net.betterpartydefence.DefenceTracker.DefenceState;

/**
 * Turns a tracked level into the text the scene overlay and info box draw, so both follow the
 * same "Defence shown as" / "Drain shown as" settings. A level is described by where it is now
 * and where it started; when the display counts from the monster's floor, the caller has
 * already taken the floor off both.
 */
final class DefenceReadout
{
	private static final int PERCENT = 100;

	private DefenceReadout()
	{
	}

	static String value(DefenceValueFormat format, long current, long base)
	{
		switch (format)
		{
			case CURRENT_OF_BASE:
				return current + "/" + base;
			case PERCENT:
				return percentRemaining(current, base) + "%";
			case CURRENT_AND_PERCENT:
				return current + " (" + percentRemaining(current, base) + "%)";
			case CURRENT:
			default:
				return Long.toString(current);
		}
	}

	/** @return the drain suffix, or null when nothing has been drained yet or drains are hidden. */
	static String drain(DefenceDrainFormat format, long current, long base)
	{
		long drained = base - current;
		if (drained <= 0 || format == DefenceDrainFormat.OFF)
		{
			return null;
		}
		return format == DefenceDrainFormat.PERCENT
			? percent(drained, base) + "%"
			: Long.toString(drained);
	}

	/** Percent of the starting value that is left, treating an empty starting value as untouched. */
	static long percentRemaining(long current, long base)
	{
		return base > 0 ? percent(Math.max(0, current), base) : PERCENT;
	}

	/** The Defence level as displayed: the full level, or how far it still sits above the monster's floor. */
	static long shownDefence(DefenceState state, boolean fullLevel)
	{
		return Math.max(0, fullLevel ? state.getCurrent() : state.getCurrent() - state.getMin());
	}

	static long shownBaseDefence(DefenceState state, boolean fullLevel)
	{
		return Math.max(0, fullLevel ? state.getBase() : state.getBase() - state.getMin());
	}

	static Color defenceColor(DefenceState state, BetterPartyDefenceConfig config)
	{
		long aboveFloor = Math.max(state.getCurrent() - state.getMin(), 0);
		if (aboveFloor == 0)
		{
			return config.defenceCappedColor();
		}
		long threshold = config.defenceLowThresholdUnit() == DefenceThresholdUnit.PERCENT
			? (state.getBase() - state.getMin()) * Math.min(PERCENT, config.defenceLowThreshold()) / PERCENT
			: config.defenceLowThreshold();
		return aboveFloor <= threshold ? config.defenceLowColor() : config.defenceHighColor();
	}

	private static long percent(long part, long whole)
	{
		return Math.round(part * 100.0 / whole);
	}
}

package net.betterpartydefence;

import lombok.Getter;
