	TEKTON("Tekton", 205, 205, 390, 390, 0, 0,
		Flag.COX_SCALED, Flag.COX_MAGIC_IS_DEFENSIVE, Flag.COX_CM_SMALL_DEFENCE_BUMP),
	TEKTON_ENRAGED("Tekton (enraged)", 205, 205, 390, 390, 0, 0,
		Flag.COX_SCALED, Flag.COX_MAGIC_IS_DEFENSIVE, Flag.COX_CM_SMALL_DEFENCE_BUMP),
	THE_HUEYCOATL("The Hueycoatl", 125, 50, 150, 50, 200, 120),
	THE_MAIDEN_OF_SUGADINTI("The Maiden of Sugadinti", 200, 350, 350, 350, 0, 0),
	THE_NIGHTMARE("The Nightmare", 150, 150, 150, 150, 600, 120),
	TUMEKENS_WARDEN("Tumeken's Warden", 150, 150, 150, 150, 20, 120),
	TZKAL_ZUK("TzKal-Zuk", 260, 150, 350, 600, 350, 0),
	TZTOK_JAD("TzTok-Jad", 480, 480, 640, 960, 0, 0),
	VASA("Vasa Nistirio", 175, 230, 1, 1, 400, 0, Flag.COX_SCALED),
	VENENATIS("Venenatis", 321, 300, 300, 200, 300, 0),
	VETION("Vet'ion", 395, 300, 430, 430, 250, 0),
	VORKATH("Vorkath", 214, 150, 560, 308, 240, 0),
	XARPUS("Xarpus", 250, 220, 1, 1, 0, 0),
	// Yama is stance-dependent: -30 Magic Defence normally, +60 after his primary target
	// attacks with magic in phases 1/2, and +81 in phase 3. DefenceTracker applies those
	// live stance changes while preserving Eye of ayak drain across them.
	YAMA("Yama", 225, 250, 320, 350, -30, 145, Flag.DEMON),
	ZEBAK("Zebak", 70, 100, 250, 140, 200, 50),
	// Zulrah's magic-def bonus is form-dependent (-45 serpentine, 0 magma, 300 tanzanite); using 0.
	// A single-value entry can't follow the rotation, so the Eye of ayak drain won't read exactly per form.
	ZULRAH("Zulrah", 300, 300, 1, 1, 0, 0);

	public enum Flag
	{
		/** The monster rolls magic defence off its Defence level rather than its Magic level. */
		MAGIC_USES_DEFENCE,
		/** In CoX the monster's Magic level scales with the defensive party-size factor, not the offensive one. */
		COX_MAGIC_IS_DEFENSIVE,
		/** A Chambers of Xeric monster, so its levels take the party-size and Challenge Mode scaling. */
		COX_SCALED,
		/** Takes a smaller Challenge Mode defensive bump than the rest of CoX (Tekton). */
		COX_CM_SMALL_DEFENCE_BUMP,
		/** A demon, so the arclight family drains it harder. */
		DEMON
	}

	private final String npcName;
	private final int baseDef;
	private final int baseMagic;
	private final int baseAtk;
	private final int baseStr;
	private final int baseMagicDef;
	private final int minDef;
	private final Set<Flag> flags;

	BossDefence(String npcName, int baseDef, int baseMagic, int baseAtk, int baseStr, int baseMagicDef, int minDef,
		Flag... flags)
	{
		this.npcName = npcName;
		this.baseDef = baseDef;
		this.baseMagic = baseMagic;
		this.baseAtk = baseAtk;
		this.baseStr = baseStr;
		this.baseMagicDef = baseMagicDef;
		this.minDef = minDef;
		this.flags = flags.length == 0 ? EnumSet.noneOf(Flag.class) : EnumSet.copyOf(Arrays.asList(flags));
	}

	public boolean has(Flag flag)
	{
		return flags.contains(flag);
	}

	/**
	 * Match a concrete NPC actor. Wardens reuse the same visible names in phases 2 and 3,
	 * but only the phase-3 actors use the normal drainable Defence model represented here.
	 * Keep name-only matching for saved/synchronised logical state, and use this method whenever
	 * a live NPC is available.
	 */
	public static BossDefence matchingNpc(int npcId, String name)
	{
		BossDefence boss = matchingNpcName(name);
		if (boss == ELIDINIS_WARDEN)
		{
			return npcId == 11761 || npcId == 11763 ? boss : null;
		}
		if (boss == TUMEKENS_WARDEN)
		{
			return npcId == 11762 || npcId == 11764 ? boss : null;
		}
		return boss;
	}

	/**
	 * The entry for an in-game NPC name. Exact first, then a word-boundary prefix so a
	 * phase suffix the table doesn't list still matches its base entry (e.g. "Vet'ion Reborn").
	 */
	public static BossDefence matchingNpcName(String name)
	{
		if (name == null || name.trim().isEmpty())
		{
			return null;
		}
		String trimmed = Text.removeTags(name).trim();
		for (BossDefence boss : values())
		{
			String candidate = Text.removeTags(boss.npcName).trim();
			if (candidate.equalsIgnoreCase(trimmed))
			{
				return boss;
			}
		}
		for (BossDefence boss : values())
		{
			String candidate = Text.removeTags(boss.npcName).trim();
			if (trimmed.regionMatches(true, 0, candidate, 0, candidate.length())
				&& trimmed.length() > candidate.length()
				&& trimmed.charAt(candidate.length()) == ' ')
			{
				return boss;
			}
		}
		return null;
	}
}

package net.betterpartydefence;

import net.runelite.client.party.messages.PartyMemberMessage;

/**
 * Lightweight BPD proximity message for one concrete supported boss. A client sends this when the
 * boss is actually rendered, allowing another BPD peer that still holds valid remembered state for
 * the same encounter to answer with an absolute {@link BpdDefenceSync} snapshot immediately.
 */
public class BpdBossPresence extends PartyMemberMessage
{
	public static final int PROTOCOL_VERSION = 1;

	private int protocolVersion;
	private int world;
	private String bossType;
	private int scopeType;
	private int scopeId;
	private int bossX;
	private int bossY;
	private int bossPlane;
	private int healthPercent;
	private long sentAtMillis;

	/** Required for party-message deserialisation. */
	public BpdBossPresence()
	{
	}

	public BpdBossPresence(
		int world,
		BossDefence boss,
		int scopeType,
		int scopeId,
		int bossX,
		int bossY,
		int bossPlane,
		int healthPercent)
	{
		this.protocolVersion = PROTOCOL_VERSION;
		this.world = world;
		this.bossType = boss == null ? null : boss.name();
		this.scopeType = scopeType;
		this.scopeId = scopeId;
		this.bossX = bossX;
		this.bossY = bossY;
		this.bossPlane = bossPlane;
		this.healthPercent = healthPercent;
		this.sentAtMillis = System.currentTimeMillis();
	}

	public BossDefence toBossType()
	{
		if (bossType == null)
		{
			return null;
		}
		try
		{
			return BossDefence.valueOf(bossType);
		}
		catch (RuntimeException ex)
		{
			return null;
		}
	}

	public int getProtocolVersion() { return protocolVersion; }
