	private static final int SYNC_HISTORY_DUPLICATE_WINDOW_TICKS = 2;
	private static final int NON_INSTANCE_HP_TOLERANCE = 20;
	private static final int NON_INSTANCE_POSITION_TOLERANCE = 16;
