package net.betterpartydefence;

import java.awt.Font;
import java.io.File;
import net.runelite.client.ui.FontManager;

/** Loads the selected tracker font, including an optional local TTF/OTF file. */
final class TrackerFontManager
{
	private final BetterPartyDefenceConfig config;
	private String cachedPath;
	private Font cachedCustom;

	TrackerFontManager(BetterPartyDefenceConfig config)
	{
		this.config = config;
	}

	Font font()
	{
		return font(config.defenceFont(), config.defenceFontSize(), config.defenceBoldText());
	}

	private Font font(TrackerFont selection, int configuredSize, boolean bold)
	{
		int size = Math.max(8, Math.min(48, configuredSize));
		Font base;
		switch (selection)
		{
			case SANS_SERIF:
				base = new Font(Font.SANS_SERIF, Font.PLAIN, size);
				break;
			case SERIF:
				base = new Font(Font.SERIF, Font.PLAIN, size);
				break;
			case MONOSPACED:
				base = new Font(Font.MONOSPACED, Font.PLAIN, size);
				break;
			case ADD_CUSTOM:
			case CUSTOM:
				base = customFont();
				if (base == null)
				{
					base = FontManager.getRunescapeSmallFont();
				}
				base = base.deriveFont((float) size);
				break;
			case RUNESCAPE:
			default:
				base = FontManager.getRunescapeSmallFont().deriveFont((float) size);
				break;
		}
		return bold ? base.deriveFont(Font.BOLD) : base.deriveFont(Font.PLAIN);
	}

	private Font customFont()
	{
		String path = config.customFontPath();
		if (path == null || path.trim().isEmpty())
		{
			return null;
		}
		if (path.equals(cachedPath))
		{
			return cachedCustom;
		}
		cachedPath = path;
		cachedCustom = loadFont(path);
		return cachedCustom;
	}

	private static Font loadFont(String path)
	{
		File file = new File(path);
		if (!file.isFile())
		{
			return null;
		}
		try
		{
			return Font.createFont(Font.TRUETYPE_FONT, file);
		}
		catch (Exception ignored)
		{
			try
			{
				return Font.createFont(Font.TYPE1_FONT, file);
			}
			catch (Exception ignoredAgain)
			{
				return null;
			}
		}
	}
}

package net.betterpartydefence;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Hitsplat;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.FakeXpDrop;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.VarbitChanged;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarPlayerID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.party.PartyService;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.specialcounter.SpecialCounterPlugin;
import net.runelite.client.plugins.specialcounter.SpecialCounterUpdate;
import net.runelite.client.plugins.specialcounter.SpecialWeapon;

/**
 * Minimal local special-attack detector for defence-draining weapons only.
 *
 * <p>This intentionally contains no infoboxes, player drops, notifications, or generic
 * special-counter UI. It exists so Better Party Defence can track the local player's
 * defence specs even when RuneLite's separate Special Attack Counter plugin is disabled.
 * When in the Hub Party session it also publishes the standard {@link SpecialCounterUpdate}
 * message if the core Special Attack Counter is not already doing so.</p>
 */
@Slf4j
@Singleton
class LocalDefenceSpecDetector
{
	private final Client client;
	private final ClientThread clientThread;
	private final PartyService partyService;
	private final PluginManager pluginManager;
	private final DefenceTracker defenceTracker;

	private int specialPercentage = -1;
	private int lastHitPointsExperience = -1;
	private int lastHpChangeCycle = -1;

	private SpecialWeapon weapon;
	private NPC target;
	private int hitsplatTick = -1;
	private boolean hpChangedOnSpecCycle;
	private final List<Hitsplat> hitsplats = new ArrayList<>();

	@Inject
	LocalDefenceSpecDetector(
		Client client,
		ClientThread clientThread,
		PartyService partyService,
		PluginManager pluginManager,
		DefenceTracker defenceTracker)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.partyService = partyService;
		this.pluginManager = pluginManager;
		this.defenceTracker = defenceTracker;
	}

	void reset()
	{
		specialPercentage = -1;
		lastHitPointsExperience = -1;
		lastHpChangeCycle = -1;
		clearPending();
	}

	void onFakeXpDrop(FakeXpDrop event)
	{
		if (event.getSkill() == Skill.HITPOINTS)
		{
			lastHpChangeCycle = client.getGameCycle();
		}
	}

	void onStatChanged(StatChanged event)
	{
		if (event.getSkill() != Skill.HITPOINTS)
		{
			return;
		}

		if (event.getXp() > lastHitPointsExperience)
		{
			lastHpChangeCycle = client.getGameCycle();
		}
		lastHitPointsExperience = event.getXp();
	}

	void onVarbitChanged(VarbitChanged event)
	{
		if (event.getVarpId() != VarPlayerID.SA_ENERGY)
		{
			return;
		}

		int current = event.getValue();
		if (specialPercentage == -1 || current >= specialPercentage)
		{
			specialPercentage = current;
			return;
		}

		// Special energy went down. Defer target/equipment reads until player/NPC update has completed.
		specialPercentage = current;
		final int serverTick = client.getTickCount();
		clientThread.invokeLater(() -> beginSpec(serverTick));
	}

	private void beginSpec(int serverTick)
	{
		SpecialWeapon used = usedSupportedWeapon();
		if (used == null)
		{
			return;
		}

		Player local = client.getLocalPlayer();
		Actor interacting = local == null ? null : local.getInteracting();
		if (!(interacting instanceof NPC))
		{
			log.debug("Local defence spec {} ignored: no NPC target", used);
			return;
		}

		NPC npc = (NPC) interacting;
		if (npc.getName() == null || BossDefence.matchingNpc(npc.getId(), npc.getName()) == null)
		{
			log.debug("Local defence spec {} ignored: unsupported target {}", used, npc.getName());
			return;
		}

		weapon = used;
		target = npc;
		hpChangedOnSpecCycle = lastHpChangeCycle == client.getGameCycle();
		hitsplatTick = serverTick + hitDelay(used, npc);
		hitsplats.clear();
		log.debug("Local defence spec armed: weapon={} target={} npc={} expectedTick={}",
			weapon, npc.getName(), npc.getIndex(), hitsplatTick);
	}

	void onHitsplatApplied(HitsplatApplied event)
	{
		if (weapon == null || target == null)
		{
			return;
		}

		Hitsplat splat = event.getHitsplat();
		if (!splat.isMine() || event.getActor() != target)
		{
			return;
		}

		if (client.getTickCount() == hitsplatTick)
		{
			hitsplats.add(splat);
		}
	}

	/** Called once per game tick before the DefenceTracker consumes its queue. */
	void onGameTick()
	{
		if (weapon == null || target == null)
		{
			return;
		}

		int tick = client.getTickCount();

		// Elder Maul is resolved from the HP-change signal by RuneLite's own special-counter logic.
		if (weapon == SpecialWeapon.ELDER_MAUL)
		{
			record(weapon, hpChangedOnSpecCycle ? 1 : 0, target);
			clearPending();
			return;
		}

		if (tick == hitsplatTick)
		{
			if (weapon == SpecialWeapon.TONALZTICS_OF_RALOS)
			{
				if (hitsplats.size() < 2)
				{
					return;
				}
				Hitsplat last = hitsplats.get(hitsplats.size() - 1);
				Hitsplat previous = hitsplats.get(hitsplats.size() - 2);
				int connected = Math.min(last.getAmount(), 1) + Math.min(previous.getAmount(), 1);
				record(weapon, connected, target);
			}
			else
			{
				if (hitsplats.isEmpty())
				{
					return;
				}
				// The weapon hitsplat is the last mine hitsplat on the target for the expected tick.
				int rawHit = hitsplats.get(hitsplats.size() - 1).getAmount();
				record(weapon, rawHit, target);
			}
			clearPending();
		}
		else if (tick > hitsplatTick)
		{
			// Magic attacks can splash without producing a HitsplatApplied event. For the two
			// supported magic special attacks, the spent special energy + armed target is enough
			// to know the attempt occurred, so preserve it as a 0-hit miss for the Magic info-box
			// history instead of silently dropping it.
			if (recordsSplashAsMiss(weapon))
			{
				log.debug("Local magic defence spec splashed with no hitsplat: {}", weapon);
				record(weapon, 0, target);
			}
			else
			{
				log.debug("Local defence spec timed out waiting for hitsplat: {}", weapon);
			}
			clearPending();
		}
	}

	/** Supported Magic attacks which can splash without a 0-damage hitsplat event. */
	static boolean recordsSplashAsMiss(SpecialWeapon used)
	{
		return used == SpecialWeapon.EYE_OF_AYAK || used == SpecialWeapon.ACCURSED_SCEPTRE;
	}

	private void record(SpecialWeapon used, int rawHit, NPC npc)
	{
		if (npc == null)
		{
			return;
		}

		int world = client.getWorld();
		int npcIndex = npc.getIndex();
		log.debug("Local defence spec: weapon={} hit={} target={} npc={} world={}",
			used, rawHit, npc.getName(), npcIndex, world);

		Player local = client.getLocalPlayer();
		String playerName = local != null && local.getName() != null ? local.getName() : "You";

		// Apply locally immediately; no party or websocket round-trip is required for our own overlay.
		// Pass the player name with the drain so the info-box hover history is tied to the same
		// accepted event as the Defence calculation.
		defenceTracker.queue(used, npcIndex, rawHit, world, playerName);

		// Hub Party Panel uses this same PartyService session. If RuneLite's core Special Attack
		// Counter is active it already sends this exact message, so never duplicate it.
		if (partyService.isInParty() && !isSpecialCounterActive())
		{
			if (local != null)
			{
				partyService.send(new SpecialCounterUpdate(npcIndex, used, rawHit, world, local.getId()));
				log.debug("Broadcast local defence spec through Hub Party session: {}", used);
			}
		}
	}

	private SpecialWeapon usedSupportedWeapon()
	{
		ItemContainer equipment = client.getItemContainer(InventoryID.WORN);
		if (equipment == null)
		{
			return null;
		}

		Item item = equipment.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		if (item == null)
		{
			return null;
		}

		int itemId = item.getId();
		for (SpecialWeapon candidate : SpecialWeapon.values())
		{
			if (DefenceTracker.isSupportedWeapon(candidate)
				&& Arrays.stream(candidate.getItemID()).anyMatch(id -> id == itemId))
			{
				return candidate;
			}
		}
		return null;
	}

	private int hitDelay(SpecialWeapon used, Actor actor)
	{
		Player local = client.getLocalPlayer();
		if (local == null || actor == null)
		{
			return 1;
		}

		WorldPoint playerPoint = local.getWorldLocation();
		WorldArea targetArea = actor.getWorldArea();
		if (playerPoint == null || targetArea == null)
		{
			return 1;
		}
		return used.getHitDelay(targetArea.distanceTo(playerPoint));
	}

	private boolean isSpecialCounterActive()
	{
		for (Plugin plugin : pluginManager.getPlugins())
		{
			if (plugin instanceof SpecialCounterPlugin && pluginManager.isPluginActive(plugin))
			{
				return true;
			}
		}
		return false;
	}

	private void clearPending()
	{
		weapon = null;
		target = null;
		hitsplatTick = -1;
		hpChangedOnSpecCycle = false;
		hitsplats.clear();
	}
}

package net.betterpartydefence;

import java.awt.image.BufferedImage;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.SpritePixels;
import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.util.ImageUtil;

/** Supplies small skill icons, optionally honoring active RuneLite sprite/theme overrides. */
final class SkillIconSource
{
	private static final int ICON_SIZE = 16;
	private final Client client;
	private final SkillIconManager skillIconManager;
	private final BetterPartyDefenceConfig config;
	private SpritePixels lastDefenceOverride;
	private SpritePixels lastMagicOverride;
	private BufferedImage themedDefence;
	private BufferedImage themedMagic;
	private BufferedImage classicDefence;
	private BufferedImage classicMagic;

	SkillIconSource(Client client, SkillIconManager skillIconManager, BetterPartyDefenceConfig config)
	{
		this.client = client;
		this.skillIconManager = skillIconManager;
		this.config = config;
	}

	BufferedImage defence()
	{
		return defence(config.defenceUseThemeSkillIcons());
	}

	BufferedImage defence(boolean useTheme)
	{
		return icon(Skill.DEFENCE, SpriteID.Staticons.DEFENCE, true, useTheme);
	}

	BufferedImage magic()
	{
		return magic(config.defenceUseThemeSkillIcons());
	}

	BufferedImage magic(boolean useTheme)
	{
		return icon(Skill.MAGIC, SpriteID.Staticons.MAGIC, false, useTheme);
	}

	private BufferedImage icon(Skill skill, int spriteId, boolean defence, boolean useTheme)
	{
		if (useTheme)
		{
			SpritePixels override = client.getSpriteOverrides().get(spriteId);
			if (override != null)
			{
				if (defence)
				{
					if (override != lastDefenceOverride || themedDefence == null)
					{
						lastDefenceOverride = override;
						themedDefence = ImageUtil.resizeImage(override.toBufferedImage(), ICON_SIZE, ICON_SIZE);
					}
					return themedDefence;
				}
				if (override != lastMagicOverride || themedMagic == null)
				{
					lastMagicOverride = override;
					themedMagic = ImageUtil.resizeImage(override.toBufferedImage(), ICON_SIZE, ICON_SIZE);
				}
				return themedMagic;
			}
		}
		if (defence)
		{
			if (classicDefence == null)
			{
				classicDefence = ImageUtil.resizeImage(skillIconManager.getSkillImage(skill), ICON_SIZE, ICON_SIZE);
			}
			return classicDefence;
		}
		if (classicMagic == null)
		{
			classicMagic = ImageUtil.resizeImage(skillIconManager.getSkillImage(skill), ICON_SIZE, ICON_SIZE);
		}
		return classicMagic;
	}
}

package net.betterpartydefence;

import java.awt.Color;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import net.betterpartydefence.DefenceTracker.DefenceState;
import net.betterpartydefence.DefenceTracker.SpecHistoryEntry;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.specialcounter.SpecialWeapon;
import net.runelite.client.ui.overlay.infobox.InfoBox;

/**
 * Status-bar (info-box) display of the monster's live defence. The box itself shows the
 * configured single value; its optional tooltip is reserved for per-encounter spec history.
 */
public class DefenceInfoBox extends InfoBox
{
	public enum Stat
	{
		DEFENCE,
		MAGIC_DEFENCE
	}

	private final DefenceTracker tracker;
	private final BetterPartyDefenceConfig config;
	private final Stat stat;
	/** The last tooltip pushed, so a per-frame render only rebuilds it on a change. */
	private String tooltip = "";

	public DefenceInfoBox(BufferedImage image, Plugin plugin, DefenceTracker tracker, BetterPartyDefenceConfig config)
	{
		this(image, plugin, tracker, config, Stat.DEFENCE);
	}

	public DefenceInfoBox(
		BufferedImage image,
		Plugin plugin,
		DefenceTracker tracker,
		BetterPartyDefenceConfig config,
		Stat stat)
	{
		super(image, plugin);
		this.tracker = tracker;
		this.config = config;
		this.stat = stat;
		setTooltip("Better Party Defence");
	}

	@Override
	public String getText()
	{
		DefenceState state = tracker.state();
		if (state == null)
		{
			return "";
		}
		updateTooltip(state);
		if (stat == Stat.MAGIC_DEFENCE)
		{
			return magicText(state);
		}

		// Intentionally share the exact same full-vs-drainable toggle as the NPC readout.
		boolean full = config.defenceShowFullLevel();
		long current = DefenceReadout.shownDefence(state, full);
		long base = DefenceReadout.shownBaseDefence(state, full);
		return infoBoxValue(current, base);
	}

	private String magicText(DefenceState state)
	{
		long rollPercent = DefenceReadout.percentRemaining(state.getMagicRoll(), state.getMagicBaseRoll());
		switch (config.magicDefenceDisplay())
		{
			case LEVEL:
				return infoBoxValue(state.getMagicLevel(), state.getMagicBaseLevel());
			case PERCENT:
				return rollPercent + "%";
			case BOTH:
				return state.getMagicDef() + " " + rollPercent + "%";
			case BONUS:
			default:
				return infoBoxValue(state.getMagicDef(), state.getMagicBaseDef());
		}
	}

	private String infoBoxValue(long current, long base)
	{
		switch (config.defenceInfoBoxValue())
		{
			case PERCENT:
				return DefenceReadout.percentRemaining(current, base) + "%";
			case DRAINED:
				return Long.toString(Math.max(0, base - current));
			case CURRENT:
			default:
				return Long.toString(current);
		}
	}

	/** Tooltip intentionally contains only spec history; current Defence/Magic data is not repeated here. */
	private void updateTooltip(DefenceState state)
	{
		String text;
		if (!config.extraInfoInInfoBox())
		{
			text = "Better Party Defence";
		}
		else
		{
			// Read history for the exact NPC state rendered above. If selection changes between
			// reads, fail closed to an empty tooltip rather than showing a previous target's count.
			List<SpecHistoryEntry> history = relevantHistory(
				tracker.specHistoryForCurrentTarget(state.getNpcIndex()));
			if (history.isEmpty())
			{
				text = "No specs yet";
			}
			else
			{
				StringBuilder tip = new StringBuilder("Spec history:");
				for (SpecSummary summary : aggregateHistory(history))
				{
					tip.append("<br>");
					if (summary.miss)
					{
						tip.append("<col=ff0000>");
					}
					tip.append(summary.playerName)
						.append(": ")
						.append(shortWeaponName(summary.weapon));
					if (summary.miss)
					{
						tip.append(" miss: ")
							.append(summary.value)
							.append("</col>");
					}
					else
					{
						tip.append(' ').append(summary.value);
					}
				}
				text = tip.toString();
			}
		}

		if (!text.equals(tooltip))
		{
			tooltip = text;
			setTooltip(text);
		}
	}

	private List<SpecHistoryEntry> relevantHistory(List<SpecHistoryEntry> history)
	{
		List<SpecHistoryEntry> relevant = new ArrayList<>();
		for (SpecHistoryEntry entry : history)
		{
			if (entry == null)
			{
				continue;
			}
			boolean include = stat == Stat.MAGIC_DEFENCE
				? DefenceTracker.drainsMagicDefence(entry.getWeapon())
				: DefenceTracker.drainsDefence(entry.getWeapon());
			if (include)
			{
				relevant.add(entry);
			}
		}
		return relevant;
	}

	/**
	 * Aggregate the hover the way the specs actually work. Percentage/fixed-effect specs are
	 * useful as a number of uses (DWH 1, 2, 3...), while damage/effect-magnitude specs such as
	 * BGS are useful as the total amount landed. Misses are always counted separately from
	 * successful specs, so they never inflate a use count or damage total. Preserve first-seen
	 * order for a stable tooltip.
	 */
	private static List<SpecSummary> aggregateHistory(List<SpecHistoryEntry> history)
	{
		List<SpecSummary> summaries = new ArrayList<>();
		for (SpecHistoryEntry entry : history)
		{
			if (entry == null)
			{
				continue;
			}
			SpecialWeapon weapon = entry.getWeapon();
			String player = entry.getPlayerName();
			if (player == null || player.trim().isEmpty())
			{
				player = "Unknown";
			}
			boolean miss = entry.getHit() <= 0;
			SpecSummary existing = null;
			for (SpecSummary summary : summaries)
			{
				if (summary.weapon == weapon && summary.miss == miss && summary.playerName.equals(player))
				{
					existing = summary;
					break;
				}
			}

			// A miss is always counted as one attempt in its own summary. It must never
			// increment a successful-use counter or contribute zero damage to a hit total.
			int amount = miss ? 1 : (historyUsesCount(weapon) ? 1 : Math.max(0, entry.getHit()));
			if (existing == null)
			{
				summaries.add(new SpecSummary(player, weapon, amount, miss));
			}
			else
			{
				existing.value += amount;
			}
		}
		return summaries;
	}

	private static boolean historyUsesCount(SpecialWeapon weapon)
	{
		if (weapon == null)
		{
			return true;
		}
		switch (weapon)
		{
			case DRAGON_WARHAMMER:
			case ELDER_MAUL:
			case ARCLIGHT:
			case DARKLIGHT:
			case EMBERLIGHT:
			case ACCURSED_SCEPTRE:
				return true;
			default:
				return false;
		}
	}

	private static final class SpecSummary
	{
		private final String playerName;
		private final SpecialWeapon weapon;
		private final boolean miss;
		private int value;

		private SpecSummary(String playerName, SpecialWeapon weapon, int value, boolean miss)
		{
			this.playerName = playerName;
			this.weapon = weapon;
			this.value = value;
			this.miss = miss;
		}
	}

	private static String shortWeaponName(SpecialWeapon weapon)
	{
		if (weapon == null)
		{
			return "Spec";
		}

		switch (weapon)
		{
			case DRAGON_WARHAMMER:
				return "DWH";
			case BANDOS_GODSWORD:
				return "BGS";
			case ELDER_MAUL:
				return "Elder maul";
			case TONALZTICS_OF_RALOS:
				return "Ralos";
			case BARRELCHEST_ANCHOR:
				return "Anchor";
			case BONE_DAGGER:
				return "Bone dagger";
			case DORGESHUUN_CROSSBOW:
				return "Dorgeshuun cbow";
			case ACCURSED_SCEPTRE:
				return "Accursed";
			case EYE_OF_AYAK:
				return "Eye of ayak";
			case ARCLIGHT:
				return "Arclight";
			case DARKLIGHT:
				return "Darklight";
			case EMBERLIGHT:
				return "Emberlight";
			case SEERCULL:
				return "Seercull";
			default:
				return weapon.name();
		}
	}

	@Override
	public Color getTextColor()
	{
		if (stat == Stat.MAGIC_DEFENCE)
		{
			return config.magicDefenceColor();
		}
		DefenceState state = tracker.state();
		return state == null ? Color.WHITE : DefenceReadout.defenceColor(state, config);
	}
}

package net.betterpartydefence;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/**
 * How the monster's live magic defence is written out. The magic-defence bonus is the
 * number the Eye of ayak drains directly, and the Magic level is what the accursed
 * sceptre and Seercull drain, so each reads like the Defence row beside it but only
 * moves for its own weapons — the percentage of the starting magic-defence roll catches
 * both.
 */
@Getter
@RequiredArgsConstructor
public enum MagicDefenceDisplay
{
	BONUS("Magic defence bonus"),
	LEVEL("Magic level"),
	PERCENT("Percent of starting roll"),
	BOTH("Bonus and percent");

	private final String label;

	@Override
	public String toString()
	{
		return label;
	}
}

package net.betterpartydefence;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

/** Which single number the status-bar defence info box shows; the full breakdown is in its tooltip. */
@Getter
@RequiredArgsConstructor
public enum DefenceInfoBoxValue
{
	CURRENT("Current defence"),
	PERCENT("Percent remaining"),
	DRAINED("Amount drained");

	private final String label;

	@Override
	public String toString()
	{
		return label;
	}
}

package net.betterpartydefence;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import lombok.Value;
import net.betterpartydefence.DefenceTracker.DefenceState;
import net.runelite.api.Point;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Shared renderer for both the NPC-attached and detached tracker.
 * Keeping the drawing in one place guarantees Detached is literally the same
 * readout as Attached; only the anchor point is different.
 */
final class DefenceOverlayRenderer
{
	private static final Color PLATE_COLOR = new Color(0, 0, 0, 150);
	private static final int GAP = 3;
	private static final int SEGMENT_GAP = 8;
	private static final int ARROW_WIDTH = 7;
	private static final int EDGE_PADDING = 2;

	private final BetterPartyDefenceConfig config;
	private final SkillIconSource skillIcons;

	@Value
	private static class Segment
	{
		BufferedImage icon;
		String text;
		Color color;
		String drain;
	}

	DefenceOverlayRenderer(BetterPartyDefenceConfig config, SkillIconSource skillIcons)
	{
		this.config = config;
		this.skillIcons = skillIcons;
	}

	/** Draw the tracker centred on an arbitrary anchor, used by the NPC overlay. */
	void renderAt(Graphics2D graphics, DefenceState state, int centreX, int baseline)
	{
		FontMetrics fm = graphics.getFontMetrics();
		List<List<Segment>> rows = rows(state);
		for (int i = 0; i < rows.size(); i++)
		{
			drawRow(graphics, fm, centreX, baseline + i * fm.getHeight(), rows.get(i));
		}
	}

	/**
	 * Draw the same tracker at (0,0) for a movable RuneLite overlay and return its
	 * exact draggable bounds.
	 */
	Dimension renderDetached(Graphics2D graphics, DefenceState state)
	{
		FontMetrics fm = graphics.getFontMetrics();
		List<List<Segment>> rows = rows(state);
		if (rows.isEmpty())
		{
			return null;
		}

		int maxRowWidth = 0;
		int maxIconHeight = 0;
		for (List<Segment> row : rows)
		{
			maxRowWidth = Math.max(maxRowWidth, rowWidth(fm, row));
			for (Segment segment : row)
			{
				if (segment.getIcon() != null)
				{
					maxIconHeight = Math.max(maxIconHeight, segment.getIcon().getHeight());
				}
			}
		}

		int firstBaseline = Math.max(fm.getAscent() + 1, maxIconHeight - 2) + EDGE_PADDING;
		int width = maxRowWidth + EDGE_PADDING * 2;
		int centreX = width / 2;
		for (int i = 0; i < rows.size(); i++)
		{
			drawRow(graphics, fm, centreX, firstBaseline + i * fm.getHeight(), rows.get(i));
		}

		int lastBaseline = firstBaseline + (rows.size() - 1) * fm.getHeight();
		int bottom = lastBaseline + Math.max(fm.getDescent() + 2, 3) + EDGE_PADDING;
		return new Dimension(width, bottom);
	}

	private List<List<Segment>> rows(DefenceState state)
	{
		Segment defence = defenceSegment(state);
		Segment magic = config.magicDefence() ? magicSegment(state) : null;
		if (magic == null)
		{
			return Collections.singletonList(Collections.singletonList(defence));
		}
		if (config.magicDefenceSameRow())
		{
			return Collections.singletonList(Arrays.asList(defence, magic));
		}
		List<List<Segment>> rows = new ArrayList<>(2);
		rows.add(Collections.singletonList(defence));
		rows.add(Collections.singletonList(magic));
		return rows;
	}

	private Segment defenceSegment(DefenceState state)
	{
		boolean full = config.defenceShowFullLevel();
		long current = DefenceReadout.shownDefence(state, full);
		long base = DefenceReadout.shownBaseDefence(state, full);
		return new Segment(iconOrNull(skillIcons.defence()),
			DefenceReadout.value(config.defenceValueFormat(), current, base),
			DefenceReadout.defenceColor(state, config),
			DefenceReadout.drain(config.defenceDrainFormat(), current, base));
	}

	private Segment magicSegment(DefenceState state)
	{
		long rollPercent = DefenceReadout.percentRemaining(state.getMagicRoll(), state.getMagicBaseRoll());
		String text;
		String drain = null;
		switch (config.magicDefenceDisplay())
		{
			case BONUS:
				text = DefenceReadout.value(config.defenceValueFormat(), state.getMagicDef(), state.getMagicBaseDef());
				drain = DefenceReadout.drain(config.defenceDrainFormat(), state.getMagicDef(), state.getMagicBaseDef());
				break;
			case LEVEL:
				text = DefenceReadout.value(config.defenceValueFormat(), state.getMagicLevel(), state.getMagicBaseLevel());
				drain = DefenceReadout.drain(config.defenceDrainFormat(), state.getMagicLevel(), state.getMagicBaseLevel());
				break;
			case PERCENT:
				if (rollPercent >= 100)
				{
					return null;
				}
				text = rollPercent + "%";
				break;
			case BOTH:
				text = rollPercent < 100 ? state.getMagicDef() + "  " + rollPercent + "%" : Long.toString(state.getMagicDef());
				drain = DefenceReadout.drain(config.defenceDrainFormat(), state.getMagicDef(), state.getMagicBaseDef());
				break;
			default:
				return null;
		}
		return new Segment(iconOrNull(skillIcons.magic()), text, config.magicDefenceColor(), drain);
	}

	private BufferedImage iconOrNull(BufferedImage image)
	{
		return config.defenceShowIcons() ? image : null;
	}

	private void drawRow(Graphics2D graphics, FontMetrics fm, int centreX, int baseline, List<Segment> segments)
	{
		int totalW = rowWidth(fm, segments);
		int x = centreX - totalW / 2;
		if (config.defenceTextPlate())
		{
			graphics.setColor(PLATE_COLOR);
			graphics.fillRect(x - 2, baseline - fm.getAscent() - 1, totalW + 4, fm.getHeight() + 2);
		}
		for (Segment segment : segments)
		{
			x = drawSegment(graphics, fm, x, baseline, segment) + SEGMENT_GAP;
		}
	}

	private static int rowWidth(FontMetrics fm, List<Segment> segments)
	{
		int totalW = SEGMENT_GAP * (segments.size() - 1);
		for (Segment segment : segments)
		{
			totalW += width(fm, segment);
		}
		return totalW;
	}

	private static int width(FontMetrics fm, Segment segment)
	{
		int w = fm.stringWidth(segment.getText());
		if (segment.getIcon() != null)
		{
			w += segment.getIcon().getWidth() + GAP;
		}
		if (segment.getDrain() != null)
		{
			w += GAP + ARROW_WIDTH + 2 + fm.stringWidth(segment.getDrain());
		}
		return w;
	}

	private int drawSegment(Graphics2D graphics, FontMetrics fm, int x, int baseline, Segment segment)
	{
		int cursor = x;
		BufferedImage image = segment.getIcon();
		if (image != null)
		{
			graphics.drawImage(image, cursor, baseline - image.getHeight() + 2, null);
			cursor += image.getWidth() + GAP;
		}
		OverlayUtil.renderTextLocation(graphics, new Point(cursor, baseline), segment.getText(), segment.getColor());
		cursor += fm.stringWidth(segment.getText());
		if (segment.getDrain() != null)
		{
			cursor += GAP;
			drawDownArrow(graphics, cursor, baseline, fm.getAscent());
			cursor += ARROW_WIDTH + 2;
			OverlayUtil.renderTextLocation(graphics, new Point(cursor, baseline), segment.getDrain(), config.defenceDrainColor());
			cursor += fm.stringWidth(segment.getDrain());
		}
		return cursor;
	}

	private void drawDownArrow(Graphics2D graphics, int x, int baseline, int ascent)
	{
		int top = baseline - ascent + 2;
		int bottom = baseline - 1;
		Polygon tri = new Polygon();
		tri.addPoint(x, top);
		tri.addPoint(x + ARROW_WIDTH, top);
		tri.addPoint(x + ARROW_WIDTH / 2, bottom);
		graphics.setColor(config.defenceDrainColor());
		graphics.fill(tri);
	}
}
